def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)

    # Try to glean a simple robust strategy from common fields
    # Defensive: determine a target from available objectives
    # Priority: avoid edges if possible, seek neutral resource if obvious, otherwise chase if evadable
    # Gather potential nearby entities without causing errors
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    allies = observation.get("allies", [])
    territory = observation.get("territory", [])
    width = observation.get("width", 0)
    height = observation.get("height", 0)

    def in_bounds(nx, ny):
        return (width == 0 or height == 0) or (0 <= nx < width and 0 <= ny < height)

    # Simple helper: compute Manhattan distance to a target
    def mdist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Build a list of candidate target positions to move toward by balancing safety and gain
    candidates = []

    # Resource collection: move toward closest resource if present
    if resources:
        # assume resources is list of [rx, ry] or dicts
        for r in resources:
            if isinstance(r, (list, tuple)) and len(r) >= 2:
                rx, ry = r[0], r[1]
            elif isinstance(r, dict) and "x" in r and "y" in r:
                rx, ry = r["x"], r["y"]
            else:
                continue
            candidates.append((mdist((x, y), (rx, ry)), (rx, ry)))
        if candidates:
            candidates.sort()
            tx, ty = candidates[0][1]
        else:
            tx, ty = x, y
    else:
        tx, ty = x, y

    # Pseud0-evade or chase: consider nearest enemy to avoid, but not too aggressive
    if enemies:
        edist = []
        for e in enemies:
            if isinstance(e, (list, tuple)) and len(e) >= 2:
                ex, ey = e[0], e[1]
            elif isinstance(e, dict) and "x" in e and "y" in e:
                ex, ey = e["x"], e["y"]
            else:
                continue
            edist.append((mdist((x, y), (ex, ey)), (ex, ey)))
        if edist:
            edist.sort()
            # Target the closest enemy to potentially intercept if safe: prefer moving away
            closest = edist[0][1]
            # Move away from closest if possible
            dx = x - closest[0]
            dy = y - closest[1]
            cand_dx = 1 if dx > 0 else (-1 if dx < 0 else 0)
            cand_dy = 1 if dy > 0 else (-1 if dy < 0 else 0)
            # If staying is better, zero movement
            if cand_dx == 0 and cand_dy == 0:
                cand_dx, cand_dy = 0, 0
        else:
            cand_dx, cand_dy = 0, 0
    else:
        cand_dx, cand_dy = 0, 0

    # Territory awareness: try to center in open area by moving toward territory center if provided
    if territory:
        # Try to move toward center of territory cell(s)
        if isinstance(territory, dict) and "center" in territory:
            tc = territory["center"]
            if isinstance(tc, (list, tuple)) and len(tc) >= 2:
                tx_t, ty_t = tc[0], tc[1]
            else:
                tx_t, ty_t = x, y
        else:
            # pick first cell in territory as target
            tcell = territory[0]
            if isinstance(tcell, (list, tuple)) and len(tcell) >= 2:
                tx_t, ty_t = tcell[0], tcell[1]
            elif isinstance(tcell, dict) and "x" in tcell and "y" in tcell:
                tx_t, ty_t = tcell["x"], tcell["y"]
            else:
                tx_t, ty_t = x, y
        # Move toward territory target modestly
        dtx = 1 if tx_t > x else (-1 if tx_t < x else 0)
        dty = 1 if ty_t > y else (-1 if ty_t < y else 0)
        # Blend by averaging with current decision
        cand_dx = dtx if cand_dx == 0 else (1 if (cand_dx > 0) == (dtx > 0) else cand_dx)
        cand_dy = dty if cand_dy == 0 else (1 if (cand_dy > 0) == (dty > 0) else cand_dy)

    # Normalize to ensure within -1..1
    dx = 0
    dy = 0
    if abs(cand_dx) > 1:
        dx = 1 if cand_dx > 0 else -1
    else:
        dx = cand_dx
    if abs(cand_dy) > 1:
        dy = 1 if cand_dy > 0 else -1
    else:
        dy = cand_dy

    # Final guard: ensure move is within allowed set and not both zero unless no better option
    if dx not in (-1, 0, 1) or dy not in (-1, 0, 1):
        dx, dy = 0, 0

    return [dx, dy]

